export const ULTRA_SKILLS={silverrush:{cooldown:8,cast:.2,duration:1.1},instinctbeam:{cooldown:12,cast:.65,duration:1.2},ultrafocus:{cooldown:24,cast:.65,duration:1.1}};
export const goku_ultra={name:'Goku Ultra Instinct',assets:['goku_ultra','goku_ultra_vfx','goku_ultra_intro','goku_ultra_intro_vfx','goku_ultra_ultimate_vfx','goku_ultra_dialogue'],stats:{hp:1200,speed:230,melee:80,skillPower:100,cooldown:100,dodgeChance:30,blinkChance:25},
 init(f){f.focusEnd=0;f.skillUses.instinctcounter=0;f.rage=0;f.rageLockUntil=0;f.rageReadyTick=null;f.personalUses=0;for(const [k,v] of Object.entries({silverrush:3,instinctbeam:2,ultrafocus:5})){f[k+'Cd']=v*f.cooldownFactor;f.skillUses[k]=0;}},
 onAct(f,s,d){if(!ULTRA_SKILLS[s])return;f[s+'Cd']=ULTRA_SKILLS[s].cooldown*f.cooldownFactor;f.skillUses[s]++;f.ultraHits=0;f.ultraTarget=d.pickTarget(f)?.uid;},
 tick(f,dt){for(const k of Object.keys(ULTRA_SKILLS))f[k+'Cd']=Math.max(0,f[k+'Cd']-dt);},
 movementSpeedMultiplier(d,f){return d.tick<f.focusEnd?1.2:1;},
 dodgeChanceBonus(d,f){return d.tick<f.focusEnd?20:0;},
 beforeHit(d,f,source,h,hits){if(h.guaranteed||h.counter||h.ultimate||f.hp<=0||d.tick<(f.rootUntil||0)||d.tick<(f.petrifyUntil||0)||f.invulnerable>0||!d.isEnemy(f,source))return false;if(!d.roll(20)||!d.evade(f,false))return false;f.skillUses.instinctcounter++;d.event('ultraCounter',f,{x:f.x,y:f.y});if(source.hp>0&&Math.hypot(source.x-f.x,source.y-f.y)<165)hits.push({source:f,target:source,value:110,counter:true,knockback:35});return true;},
 onDeath(d,f){f.focusEnd=0;},
 updateAction(d,f,o,hits,dx,dy,dist,dt){const spec=ULTRA_SKILLS[f.state];if(!spec)return false;const t=d.fighters.find(t=>t.uid===f.ultraTarget&&t.hp>0&&d.isEnemy(f,t))||o;
  if(f.state==='silverrush'){const tx=t.x-f.x,ty=t.y-f.y,n=Math.hypot(tx,ty)||1;if(f.age<.5&&d.tick>=(f.rootUntil||0)){const move=Math.min(Math.max(0,n-65),560*dt);f.x+=tx/n*move;f.y+=ty/n*move;d.clampPosition(f);}while(f.ultraHits<3&&f.age>=[.25,.52,.82][f.ultraHits]){const i=f.ultraHits++;if(Math.hypot(t.x-f.x,t.y-f.y)<120){hits.push({source:f,target:t,value:[50,60,90][i],knockback:i===2?45:0});d.event('ultraStrike',f,{x:t.x,y:t.y,skill:'silverrush'});}}}
  else if(f.age>=spec.cast&&!f.hit){f.hit=true;if(f.state==='ultrafocus'){f.focusEnd=d.tick+360;f.rage=Math.min(100,f.rage+20);if(f.rage>=100&&f.rageReadyTick===null)f.rageReadyTick=d.tick;d.event('ultraFocusOn',f,{x:f.x,y:f.y});}
   else if(f.state==='instinctbeam'){if(d.tick>=(f.rootUntil||0)){const n=Math.hypot(dx,dy)||1;f.x-=dy/n*38;f.y+=dx/n*38;d.clampPosition(f);}const tx=t.x-f.x,ty=t.y-f.y,n=Math.hypot(tx,ty)||1;f.face=Math.sign(tx)||f.face;d.shots.push({id:f.id,ownerUid:f.uid,kind:'instinctbeam',skill:'instinctbeam',damage:240,radius:28,x:f.x+tx/n*40,y:f.y+ty/n*40,vx:tx/n*780,vy:ty/n*780,life:1.6,piercing:true,hitUids:[],impactEvent:'ultraImpact'});d.event('fire',f,{skill:'instinctbeam'});}}
  if(f.age>=spec.duration){f.state='idle';f.age=0;}return true;
 },
 chooseSkill(d,f,o,dx,dy,dist){for(const k of ['ultrafocus','instinctbeam','silverrush'])if(f[k+'Cd']===0&&(k==='ultrafocus'?dist<600:k==='instinctbeam'?dist>140&&dist<700:dist<340)){d.act(f,k,dx,dy);return true;}return false;}
};
export function ultraPose(f,hurt=false){if(f.introAge!=null){const row=f.introAge<.7?0:f.introAge<1.65?1:2,start=[0,.7,1.65][row],duration=[.7,.95,.85][row];return {row,frame:Math.min(5,Math.floor((f.introAge-start)/duration*6))};}const s=hurt?'hurt':f.state,spec=ULTRA_SKILLS[s];return {row:({idle:0,run:1,melee:f.combo%2?2:3,dash:4,guard:5,hurt:6,defeat:7,instinctcounter:8,silverrush:9,instinctbeam:10,ultrafocus:11})[s]??0,frame:spec?Math.min(5,Math.floor(f.age/spec.duration*6)):['defeat','hurt','melee','dash','guard'].includes(s)?Math.min(5,Math.floor(f.age*10)):Math.floor(f.age*9)%6};}
